/* Enhancement light follows the equipped sword, bow, or staff. */
MW.auraBand=p=>p.equip?.weapon?Math.min(2,Math.floor((p.upgrade||0)/5)):0;
(()=>{const R=MW.Renderer.prototype,base=R.player;
R.player=function(p,face=0,frame=0){const original=base.call(this,p,face,frame),band=MW.auraBand(p);if(!band)return original;const weapon=MW.items.find(i=>i.id===p.equip.weapon),kind=weapon?.kind||'sword',color=band===2?'#ffd586':'#86e0ed';return this.art('aura11:'+band+':'+p.job+':'+p.equip.weapon+':'+p.equip.armor+':'+face+':'+frame+':'+!!p.promotions?.includes(p.job),80,90,c=>{c.save();if(face===3){c.translate(80,0);c.scale(-1,1);}const glow=(x,y,w,h)=>{c.globalAlpha=band===2?.22:.15;this.rect(c,x-5,y-4,w+10,h+8,color);c.globalAlpha=.5;this.rect(c,x-2,y-2,w+4,h+4,color);};if(kind==='bow'){for(let y=0;y<36;y+=3){const x=59+Math.round(Math.sin(y/36*Math.PI)*9);glow(x,40+y,3,3);}}else if(kind==='staff'){glow(60,39,3,43);glow(57,31,9,11);}else glow(60,37,4,41);c.restore();c.drawImage(original,0,0);c.save();if(face===3){c.translate(80,0);c.scale(-1,1);}c.globalAlpha=.9;if(kind==='bow'){this.rect(c,69,56,1,6,color);this.rect(c,62,43,1,3,color);}else if(kind==='staff'){this.rect(c,59,31,5,1,'#efffff');this.rect(c,57,35,1,4,color);}else this.rect(c,64,38,1,34,color);if(band===2){for(const [x,y] of [[55,43],[68,60],[56,75]]){this.rect(c,x-2,y,5,1,'#fff0bc');this.rect(c,x,y-2,1,5,'#fff0bc');}}c.restore();});};
R.weaponSparkles=function(p,face=0){const band=MW.auraBand(p);if(!band)return;const c=this.ctx,color=band===2?'#ffdf9d':'#a8edf3';c.save();for(let i=0;i<(band===2?7:4);i++){const phase=(this.time*.65+i*.23)%1,localX=61+Math.sin(i*2.4+this.time)*9,localY=80-phase*46,x=p.x-40+(face===3?80-localX:localX),y=p.y-90+localY;c.globalAlpha=Math.sin(phase*Math.PI)*.85;this.rect(c,x,y,2,2,color);if(band===2)this.rect(c,x-1,y+1,4,1,'#fff1c1');}c.restore();};
})();
